let lang=localStorage.getItem('fl-lang')||'zh',view='overview',rows=[],name='Retail analytics.csv',history=[],redoStack=[],page=0,search='',chartType='bar',chartX='region',chartY='revenue',chartAgg='sum';
const words={overview:['分析概览','Overview'],data:['数据工作台','Data workspace'],transform:['清洗与变换','Clean & transform'],visual:['可视化探索','Visual explorer'],pipeline:['操作流水线','Pipeline'],help:['使用指南','Guide'],workspace:['工作空间','Workspace'],analysis:['分析工具','ANALYSIS TOOLS'],local:['浏览器本地处理','Processed in your browser'],privacy:['数据保留在你的设备中','Your data stays on your device'],import:['导入数据','Import data'],export:['导出','Export'],subtitle:['从数据到洞察，让每一步清晰可见。','From data to insight. See every step clearly.'],default:['默认示例数据','Default sample dataset'],total:['总行数','Total rows'],cols:['数据列','Columns'],missing:['缺失单元格','Missing cells'],quality:['数据完整率','Completeness'],live:['实时分析','Live analysis'],numeric:['数值列','numeric columns'],records:['条记录','records'],clean:['完整单元格占比','Share of complete cells'],revenue:['收入分布','Revenue distribution'],trend:['月度趋势','Monthly trend'],preview:['数据预览','Data preview'],full:['打开数据表','Open full table'],filter:['筛选','Filter'],reset:['重置示例','Reset sample'],save:['设为默认','Set as default'],undo:['撤销','Undo'],redo:['重做','Redo'],apply:['应用操作','Apply operation'],cancel:['取消','Cancel'],close:['关闭','Close'],empty:['没有符合条件的数据','No matching records'],column:['数据列','Column'],operation:['操作','Operation'],value:['值','Value'],group:['分组聚合','Group & aggregate'],pivot:['透视表','Pivot table'],join:['连接数据','Join data'],count:['计数','Count'],sum:['求和','Sum'],mean:['均值','Mean'],median:['中位数','Median'],min:['最小值','Min'],max:['最大值','Max'],std:['标准差','Std. deviation'],nunique:['唯一值计数','Unique count'],by:['分组字段','Group by'],metric:['指标字段','Measure'],agg:['聚合方式','Aggregation'],sort:['排序','Sort'],asc:['升序','Ascending'],desc:['降序','Descending'],fill:['填充缺失值','Fill missing'],dropna:['删除缺失行','Drop missing rows'],dedup:['删除重复行','Drop duplicates'],rename:['重命名列','Rename column'],drop:['删除列','Drop column'],cast:['转换类型','Convert type'],compute:['计算新列','Calculated column'],text:['文本变换','Text transform'],sample:['抽样行','Sample rows'],rolling:['滚动均值','Rolling mean'],date:['日期分桶','Date bucket'],describe:['描述性统计','Descriptive statistics'],correlation:['相关性矩阵','Correlation matrix'],qualitytitle:['数据质量诊断','Data quality profile'],chart:['图表类型','Chart type'],bar:['柱状图','Bar chart'],line:['折线图','Line chart'],scatter:['散点图','Scatter plot'],hist:['直方图','Histogram'],donut:['环形图','Donut chart'],x:['横轴 / 类别','X / category'],y:['纵轴 / 数值','Y / measure'],download:['下载图表 SVG','Download chart SVG'],clear:['清空流水线','Clear pipeline'],python:['对应 pandas 代码','Equivalent pandas code'],source:['源数据','Source data'],steps:['操作步骤','Transformation steps'],guide:['无代码，也能深入分析','Deep analysis without code'],search:['搜索所有单元格…','Search all cells…'],edit:['双击单元格编辑；点击列名排序','Double-click cells to edit; click headers to sort'],showing:['显示','Showing'],of:['共','of'],load:['加载','Load'],url:['数据 URL','Data URL'],paste:['粘贴 CSV / TSV / JSON','Paste CSV / TSV / JSON'],choose:['选择文件','Choose file'],filetip:['支持 CSV、TSV 和 JSON 记录数组；支持引号和多行字段。','CSV, TSV and JSON record arrays; quoted and multiline fields supported.'],urltip:['URL 必须允许跨域访问（CORS）。','The URL must allow cross-origin access (CORS).'],success:['操作已完成','Operation complete'],error:['操作失败：','Operation failed: '],defaultsaved:['默认数据已保存到此浏览器','Default data saved in this browser'],newname:['新列名称','New column name'],right:['右侧数据（CSV）','Right dataset (CSV)'],jointype:['连接方式','Join type'],inner:['内连接','Inner join'],left:['左连接','Left join'],key:['连接键','Join key'],rowslabel:['行数','Row count'],window:['窗口大小','Window size'],type:['目标类型','Target type'],number:['数字','Number'],string:['文本','String'],month:['按月','By month'],year:['按年','By year'],lower:['转小写','Lowercase'],upper:['转大写','Uppercase'],trim:['去首尾空格','Trim spaces'],length:['文本长度','String length'],second:['第二字段','Second column'],operator:['运算符','Operator'],constant:['常数（第二字段留空时使用）','Constant (if second column is empty)'],none:['不使用','None'],notes:['图表点击可筛选；清洗操作可撤销。','Click charts to filter; transformations are undoable.'],duplicates:['重复行','Duplicate rows'],unique:['唯一值','Unique'],missingrate:['缺失率','Missing rate'],outliers:['异常值（IQR）','Outliers (IQR)'],original:['原始数据','Original data'],notall:['涵盖常用 pandas 工作流，并非完整 pandas API；导出的 Python 代码可继续扩展。','Covers common pandas workflows, not the entire pandas API; extend analysis with exported Python code.'],limit:['建议不超过 50,000 行；数据存储和处理均在浏览器中。','Recommended up to 50,000 rows; data storage and processing happen in your browser.'],clearDefault:['恢复内置默认数据','Restore built-in default'],exportJson:['导出 JSON','Export JSON'],exportCsv:['导出 CSV','Export CSV'],exportPy:['导出 Python','Export Python'],exportFlow:['导出流程 JSON','Export workflow JSON'],importFlow:['导入流程 JSON','Import workflow JSON'],format:['数据格式','Data format'],equals:['等于','Equals'],contains:['包含','Contains'],gt:['大于','Greater than'],lt:['小于','Less than'],notnull:['非空','Not missing'],null:['为空','Missing'],condition:['条件','Condition'],settitle:['导入你的数据','Bring your data'],ready:['准备开始探索','Ready to explore'],exporttitle:['导出分析结果','Export your analysis'],datatype:['数据类型','Data type']};
