const t=k=>(words[k]||[k,k])[lang==='zh'?0:1],fmt=n=>n===null?'—':typeof n==='number'?n.toLocaleString(lang==='zh'?'zh-CN':'en-US',{maximumFractionDigits:2}):String(n??'—');
try{rows=JSON.parse(localStorage.getItem('fl-default')||'null')||E.demo()}catch{rows=E.demo()}
let source=structuredClone(rows);const cols=()=>E.columns(rows),nums=()=>cols().filter(c=>E.numeric(rows,c)),options=(list,selected)=>list.map(c=>`<option value="${esc(c)}" ${c===selected?'selected':''}>${esc(words[c]?t(c):c)}</option>`).join('');
const field=(key,id,list,selected)=>`<label>${t(key)}<select id="${id}">${options(list,selected)}</select></label>`,input=(key,id,value='')=>`<label>${t(key)}<input id="${id}" value="${esc(value)}"></label>`;
function toast(s){$('.toast')?.remove();let el=document.createElement('div');el.className='toast';el.textContent=s;document.body.append(el);setTimeout(()=>el.remove(),3500)}
function commit(next,label,code,recipe=null){if(!Array.isArray(next))throw Error('Invalid result');history.push({before:structuredClone(rows),label,code,recipe});rows=next;redoStack=[];page=0;render();toast(t('success'))}
function download(text,filename,type='text/plain'){let u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function py(){return `import pandas as pd\n\ndf = pd.read_csv("input.csv")\n${history.map(s=>s.code).join('\n')}\n\ndf.to_csv("result.csv", index=False)\n`}
function render(){document.documentElement.lang=lang;let c=cols();if(!c.includes(chartX))chartX=c[0];if(!c.includes(chartY))chartY=nums()[0]||c[0];$('#app').innerHTML=`<aside><div class="brand"><span class="logo">▥</span>FrameLab<span style="color:#bbc1cc;font-size:12px">/</span></div><div class="caption">${t('analysis')}</div><nav>${['overview','data','transform','visual','pipeline','help'].map((v,i)=>`<button class="nav ${view===v?'active':''}" data-view="${v}"><span>${['◫','▦','⇄','◷','☷','ⓘ'][i]}</span>${t(v)}</button>`).join('')}</nav><div class="sidebottom"><span class="dot"></span>${t('local')}<p style="font-size:10px">${t('privacy')}</p></div></aside><main><header><div class="crumb">${t('workspace')}<b>/ &nbsp; ${esc(name)}</b></div><div class="actions"><button id="language">${lang==='zh'?'EN · English':'中文 · ZH'}</button><button id="undo" ${history.length?'':'disabled'}>↶ ${t('undo')}</button><button id="redo" ${redoStack.length?'':'disabled'}>↷ ${t('redo')}</button><button id="export">↗ ${t('export')}</button><button class="primary" id="import">＋ ${t('import')}</button></div></header><div class="workspace"><div class="heading"><div><h1>${t(view)}</h1><p>${t('subtitle')}</p></div><span class="badge"><span class="dot"></span>${t('live')}</span></div>${view==='overview'?overview():view==='data'?dataView():view==='transform'?transformView():view==='visual'?visualView():view==='pipeline'?pipelineView():helpView()}</div></main>`;bind();if(view==='overview'){draw($('#mainchart'),'bar','region','revenue','sum');draw($('#trendchart'),'line','date','revenue','sum',true)}if(view==='visual')draw($('#explorechart'),chartType,chartX,chartY,chartAgg);}
function stats(){let c=cols(),m=rows.reduce((s,r)=>s+c.filter(k=>E.missing(r[k])).length,0),q=rows.length*c.length?100*(1-m/(rows.length*c.length)):100;return `<div class="stats">${[[t('total'),rows.length,`${rows.length} ${t('records')}`,'▤'],[t('cols'),c.length,`${nums().length} ${t('numeric')}`,'▦'],[t('missing'),m,`${fmt(100-q)}%`,'◌'],[t('quality'),fmt(q)+'%',t('clean'),'✧']].map(a=>`<div class="card"><div class="stathead">${a[0]}<span class="icon">${a[3]}</span></div><div class="statnum">${typeof a[1]==='number'?fmt(a[1]):a[1]}</div><div class="statfoot"><em>${a[2]}</em></div></div>`).join('')}</div>`}
function overview(){return stats()+`<div class="grid"><section class="card"><div class="cardhead"><div><h2>${cols().includes('revenue')?t('revenue'):t('bar')}</h2><div class="sub">${t('notes')}</div></div><span class="pill">${t('sum')}</span></div><svg id="mainchart" class="chart"></svg></section><section class="card"><div class="cardhead"><div><h2>${t('trend')}</h2><div class="sub">${esc(name)}</div></div><span class="legend">● ${t('revenue')}</span></div><svg id="trendchart" class="chart"></svg></section></div><section class="card"><div class="cardhead"><h2>${t('preview')} <span class="sub">${esc(name)}</span></h2><button data-view="data" class="small">${t('full')} →</button></div>${table(rows.slice(0,7),false)}</section>`}
function table(data,editable=true){let c=cols();return `<div class="tablewrap"><table><thead><tr><th>#</th>${c.map(k=>`<th data-sort="${esc(k)}"><span class="type">${E.numeric(rows,k)?'#':'Aa'}</span>${esc(k)} ↕</th>`).join('')}</tr></thead><tbody>${data.map((r,i)=>`<tr><td style="color:#a5adba">${i+1+page*40}</td>${c.map(k=>`<td ${editable?'data-cell="'+esc(k)+'" data-row="'+rows.indexOf(r)+'"':''}>${E.missing(r[k])?'<span style="color:#b0b8c4">null</span>':esc(fmt(r[k]))}</td>`).join('')}</tr>`).join('')}</tbody></table>${data.length?'':`<div class="empty">${t('empty')}</div>`}</div>`}
function dataView(){let filtered=rows.filter(r=>Object.values(r).some(v=>String(v??'').toLowerCase().includes(search.toLowerCase())));page=Math.min(page,Math.max(0,Math.ceil(filtered.length/40)-1));return `${stats()}<div class="tools"><button id="quickfilter">${t('filter')}</button><button id="saveDefault">${t('save')}</button><button id="reset">${t('reset')}</button><button id="clearDefault">${t('clearDefault')}</button><input id="search" placeholder="${t('search')}" value="${esc(search)}" style="max-width:280px;margin-left:auto"></div><section class="card"><div class="cardhead"><h2>${t('data')}</h2><span class="sub">${t('edit')}</span></div>${table(filtered.slice(page*40,(page+1)*40))}<div class="tablefoot"><span>${t('showing')} ${filtered.length?page*40+1:0}–${Math.min((page+1)*40,filtered.length)} / ${filtered.length} ${t('records')}</span><div class="actions"><button id="prev" class="small" ${page===0?'disabled':''}>←</button><span>${page+1}</span><button id="next" class="small" ${(page+1)*40>=filtered.length?'disabled':''}>→</button></div></div></section>`}
let op='filter';function transformView(){return `<div class="panel"><section class="card"><div class="form">${field('operation','op',['filter','sort','fill','dropna','dedup','rename','drop','cast','compute','text','sample','rolling','date','group','pivot','join'],op)}<div id="opform">${opform()}</div><button class="primary" id="apply">${t('apply')} →</button></div><div class="callout">${t('notes')}<br>${t('notall')}</div></section><div><section class="card"><div class="cardhead"><h2>${t('qualitytitle')}</h2><span class="pill">${rows.length} ${t('records')}</span></div>${quality()}</section><section class="card" style="margin-top:20px"><div class="cardhead"><h2>${t('describe')}</h2></div>${describe()}</section></div></div>`}
function opform(){let c=cols(),n=nums();let base=field('column','col',c,c[0]);if(op==='group')return field('by','col',c,c[0])+field('metric','metric',c,n[0])+field('agg','agg',['sum','mean','median','count','nunique','min','max','std'],'sum');if(op==='pivot')return field('by','col',c,c[0])+field('column','second',c,c[1])+field('metric','metric',n,n[0])+field('agg','agg',['sum','mean','count','min','max'],'sum');if(op==='join')return field('key','col',c,c[0])+field('jointype','method',['left','inner'],'left')+`<label>${t('right')}<textarea id="value" rows="7" placeholder="${esc(c[0])},segment\nEast,Premium"></textarea></label>`;if(op==='dedup')return '';if(op==='sample')return input('rowslabel','value',Math.min(20,rows.length));if(op==='filter')return base+field('condition','method',['equals','contains','gt','lt','notnull','null'],'equals')+input('value','value');if(op==='sort')return base+field('sort','method',['asc','desc'],'asc');if(op==='fill')return base+field('agg','method',['constant','mean','median','min','max'],'constant')+input('value','value',0);if(op==='rename')return base+input('newname','value','new_column');if(op==='cast')return base+field('type','method',['number','string','date'],'number');if(op==='compute')return base+field('second','second',['',...n],'')+field('operator','method',['+','-','*','/','%'],'-')+input('constant','value',1)+input('newname','newname','calculated');if(op==='text')return base+field('operation','method',['lower','upper','trim','length'],'trim');if(op==='rolling')return field('column','col',n,n[0])+input('window','value',3)+input('newname','newname','rolling_mean');if(op==='date')return base+field('operation','method',['month','year'],'month')+input('newname','newname','period');return base}
function quality(){return cols().map(c=>{let v=E.values(rows,c),rate=rows.length?(rows.length-v.length)/rows.length*100:0;return `<div class="qualityrow"><span>${esc(c)}</span><div class="meter" title="${t('missingrate')}: ${fmt(rate)}%"><span style="width:${100-rate}%"></span></div><span>${fmt(100-rate)}%</span></div>`}).join('')+`<div class="sub">${t('duplicates')}: ${rows.length-new Set(rows.map(r=>JSON.stringify(cols().map(c=>r[c]??null)))).size}</div>`}
function describe(){let ns=nums();return `<div class="tablewrap"><table><thead><tr><th>${t('column')}</th>${['count','mean','std','min','median','max','outliers'].map(k=>`<th>${t(k)}</th>`).join('')}</tr></thead><tbody>${ns.map(c=>{let a=E.values(rows,c).map(Number),q1=E.quantile(a,.25),q3=E.quantile(a,.75);return `<tr><td>${esc(c)}</td>${['count','mean','std','min','median','max'].map(k=>`<td>${fmt(E.aggregate(a,k))}</td>`).join('')}<td>${a.filter(v=>v<q1-1.5*(q3-q1)||v>q3+1.5*(q3-q1)).length}</td></tr>`}).join('')}</tbody></table></div>`}
function applyRecipe(a){let {op,c,method,v,second,metric,agg,newname}=a,r=structuredClone(rows),code='',q=x=>JSON.stringify(x);if(!rows.length)throw Error(lang==='zh'?'请先加载数据':'Load data first');let ensure=n=>{if(!n.trim()||cols().includes(n))throw Error(lang==='zh'?'新列名称不能为空或重复':'New column name must be nonempty and unique')};switch(op){case'filter':r=r.filter(x=>method==='null'?E.missing(x[c]):method==='notnull'?!E.missing(x[c]):method==='contains'?String(x[c]??'').includes(v):method==='gt'?E.num(x[c])&&Number(x[c])>Number(v):method==='lt'?E.num(x[c])&&Number(x[c])<Number(v):String(x[c]??'')===String(v));code=method==='null'?`df = df[df[${q(c)}].isna()]`:method==='notnull'?`df = df[df[${q(c)}].notna()]`:method==='contains'?`df = df[df[${q(c)}].astype(str).str.contains(${q(v)}, regex=False, na=False)]`:`df = df[df[${q(c)}] ${method==='gt'?'>':method==='lt'?'<':'=='} ${E.numeric(rows,c)&&E.num(v)?Number(v):q(v)}]`;break;case'sort':r.sort((a,b)=>{let x=a[c],y=b[c];if(E.missing(x))return E.missing(y)?0:1;if(E.missing(y))return-1;let n=E.num(x)&&E.num(y)?Number(x)-Number(y):String(x).localeCompare(String(y));return method==='desc'?-n:n});code=`df = df.sort_values(${q(c)}, ascending=${method==='desc'?'False':'True'})`;break;case'fill':{let value=method==='constant'?(E.num(v)?Number(v):v):E.aggregate(E.values(r,c),method);r.forEach(x=>{if(E.missing(x[c]))x[c]=value});code=`df[${q(c)}] = df[${q(c)}].fillna(${method==='constant'?q(value):`df[${q(c)}].${method}()`})`;break}case'dropna':r=r.filter(x=>!E.missing(x[c]));code=`df = df.dropna(subset=[${q(c)}])`;break;case'dedup':{let seen=new Set;r=r.filter(x=>{let k=JSON.stringify(cols().map(c=>x[c]??null));if(seen.has(k))return false;seen.add(k);return true});code='df = df.drop_duplicates()';break}case'rename':ensure(v);r.forEach(x=>{x[v]=x[c];delete x[c]});code=`df = df.rename(columns={${q(c)}: ${q(v)}})`;break;case'drop':if(cols().length===1)throw Error('Cannot remove final column');r.forEach(x=>delete x[c]);code=`df = df.drop(columns=[${q(c)}])`;break;case'cast':r.forEach(x=>{x[c]=E.missing(x[c])?null:method==='number'?(E.num(x[c])?Number(x[c]):null):method==='date'?(Number.isNaN(Date.parse(x[c]))?null:new Date(x[c]).toISOString().slice(0,10)):String(x[c])});code=method==='number'?`df[${q(c)}] = pd.to_numeric(df[${q(c)}], errors="coerce")`:method==='date'?`df[${q(c)}] = pd.to_datetime(df[${q(c)}], errors="coerce").dt.strftime("%Y-%m-%d")`:`df[${q(c)}] = df[${q(c)}].astype("string")`;break;case'compute':ensure(newname);r.forEach(x=>{let b=second?x[second]:v;if(!E.num(x[c])||!E.num(b)){x[newname]=null;return}let left=Number(x[c]),right=Number(b);x[newname]=method==='+'?left+right:method==='-'?left-right:method==='*'?left*right:right===0?null:method==='/'?left/right:left%right});code=`df[${q(newname)}] = pd.to_numeric(df[${q(c)}], errors="coerce") ${method} ${second?`pd.to_numeric(df[${q(second)}], errors="coerce")`:Number(v)}${['/','%'].includes(method)?'\ndf = df.replace([float("inf"), -float("inf")], float("nan"))':''}`;break;case'text':r.forEach(x=>{if(!E.missing(x[c]))x[c]=method==='lower'?String(x[c]).toLowerCase():method==='upper'?String(x[c]).toUpperCase():method==='trim'?String(x[c]).trim():String(x[c]).length});code=`df[${q(c)}] = df[${q(c)}].astype("string").str.${({trim:'strip',length:'len'})[method]||method}()`;break;case'sample':{let count=Number(v);if(!Number.isInteger(count)||count<0||count>r.length)throw Error('Invalid sample size');for(let i=r.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[r[i],r[j]]=[r[j],r[i]]}r=r.slice(0,count);code=`df = df.sample(n=${count})`;break}case'rolling':ensure(newname);{let w=Number(v);if(!Number.isInteger(w)||w<1)throw Error('Invalid window');r.forEach((x,i)=>x[newname]=E.aggregate(rows.slice(Math.max(0,i-w+1),i+1).map(y=>y[c]),'mean'));code=`df[${q(newname)}] = df[${q(c)}].rolling(${w}, min_periods=1).mean()`;break}case'date':ensure(newname);r.forEach(x=>{let d=E.missing(x[c])?null:new Date(x[c]);x[newname]=!d||Number.isNaN(d.getTime())?null:d.toISOString().slice(0,method==='year'?4:7)});code=`df[${q(newname)}] = pd.to_datetime(df[${q(c)}], errors="coerce").dt.strftime("${method==='year'?'%Y':'%Y-%m'}")`;break;case'group':r=E.group(r,[c],metric,agg);code=`df = df.groupby(${q(c)}, dropna=False, as_index=False).agg(**{${q(metric+'_'+agg)}: (${q(metric)}, ${q(agg)})})`;break;case'pivot':if(c===second)throw Error('Use different index and column fields');r=E.pivot(r,c,second,metric,agg);code=`df = df.pivot_table(index=${q(c)}, columns=${q(second)}, values=${q(metric)}, aggfunc=${q(agg)}, dropna=False).reset_index()`;break;case'join':{let right=E.parse(v);if(!E.columns(right).includes(c))throw Error('Join key missing from right data');r=E.join(r,right,c,method);code=`from io import StringIO\nright = pd.read_csv(StringIO(${q(v)}))\ndf = df.merge(right, on=${q(c)}, how=${q(method)}, suffixes=("", "_right"))`;break}default:throw Error('Unknown operation')};return {r,code}}
function visualView(){return `<div class="panel"><section class="card"><div class="form">${field('chart','charttype',['bar','line','scatter','hist','donut','correlation'],chartType)}${field('x','chartx',cols(),chartX)}${field('y','charty',nums(),chartY)}${field('agg','chartagg',['sum','mean','median','count','min','max'],chartAgg)}<button id="downloadChart">${t('download')}</button></div><div class="callout">${t('notes')}</div></section><section class="card"><div class="cardhead"><div><h2>${t(chartType)}</h2><div class="sub">${esc(chartX)} × ${esc(chartY)} · ${t(chartAgg)}</div></div><span class="pill">${rows.length} ${t('records')}</span></div><svg id="explorechart" class="chart" style="height:440px"></svg><div class="sub">${t('notes')}</div></section></div>`}
function draw(svg,type,x,y,agg,monthly=false){if(!svg)return;svg.setAttribute('viewBox','0 0 650 300');svg.setAttribute('role','img');svg.setAttribute('aria-label',`${t(type)} ${x} ${y}`);let actualCols=cols();if(!actualCols.includes(x))x=actualCols.find(c=>!E.numeric(rows,c))||actualCols[0];if(!actualCols.includes(y))y=nums()[0];if(!rows.length||!y){svg.innerHTML=`<text x="250" y="150">${t('empty')}</text>`;return}let data=rows;if(monthly)data=rows.map(r=>({...r,[x]:String(r[x]).slice(0,7)}));if(type==='correlation'){let ns=nums().slice(0,8),size=240/Math.max(1,ns.length);svg.innerHTML=ns.map((a,i)=>`<text x="${130+i*size+size/2}" y="28" text-anchor="middle">${esc(a.slice(0,10))}</text><text x="115" y="${50+i*size+size/2}" text-anchor="end">${esc(a.slice(0,13))}</text>`).join('')+ns.flatMap((a,i)=>ns.map((b,j)=>{let v=E.corr(rows,a,b);return `<rect x="${130+j*size}" y="${42+i*size}" width="${size-2}" height="${size-2}" fill="${v===null?'#eee':v>=0?`rgba(83,105,237,${.1+.85*v})`:`rgba(234,141,124,${.1-.85*v})`}"/><text x="${130+j*size+size/2}" y="${42+i*size+size/2+4}" text-anchor="middle" style="fill:${v>.6?'white':'#505c73'}">${v===null?'—':v.toFixed(2)}</text>`})).join('');return}
let pairs;if(type==='scatter'){pairs=data.filter(r=>E.num(r[x])&&E.num(r[y])).slice(0,3000).map(r=>[Number(r[x]),Number(r[y])]);if(!pairs.length){svg.innerHTML=`<text x="130" y="150">${lang==='zh'?'散点图需要两个数值字段':'Scatter requires two numeric columns'}</text>`;return}}else if(type==='hist'){let a=E.values(data,y).filter(E.num).map(Number),lo=Math.min(...a),hi=Math.max(...a),width=(hi-lo||1)/10;pairs=Array.from({length:10},(_,i)=>[fmt(lo+i*width),a.filter(v=>Math.min(9,Math.floor((v-lo)/width))===i).length])}else{let g=E.group(data,[x],y,agg);pairs=g.map(r=>[r[x]??'null',r[y+'_'+agg]??0]);if(type==='line')pairs.sort((a,b)=>String(a[0]).localeCompare(String(b[0])));pairs=pairs.slice(0,24)}if(!pairs.length){svg.innerHTML='';return}let max=Math.max(...pairs.map(p=>p[1]),0)||1,min=Math.min(...pairs.map(p=>p[1]),0),range=max-min||1,yy=v=>245-(v-min)/range*200;let grid=Array.from({length:5},(_,i)=>{let v=min+i/4*range;return `<line x1="58" y1="${yy(v)}" x2="625" y2="${yy(v)}"/><text x="48" y="${yy(v)+4}" text-anchor="end">${Math.abs(v)>1000?fmt(v/1000)+'k':fmt(v)}</text>`}).join('');let colors=['#5369ed','#8898ff','#b3befc','#4cbca7','#f2be75','#93a5b9'];if(type==='donut'){let positive=pairs.filter(p=>p[1]>0),total=positive.reduce((s,p)=>s+p[1],0),start=0;svg.innerHTML=positive.map((p,i)=>{let f=p[1]/total;let res=`<circle cx="225" cy="145" r="83" fill="none" stroke="${colors[i%6]}" stroke-width="33" stroke-dasharray="${f*521.5} ${521.5-f*521.5}" stroke-dashoffset="${-start*521.5}" transform="rotate(-90 225 145)"><title>${esc(p[0])}: ${fmt(p[1])}</title></circle><rect x="380" y="${45+i*22}" width="8" height="8" rx="2" fill="${colors[i%6]}"/><text x="400" y="${53+i*22}">${esc(String(p[0]).slice(0,20))} · ${fmt(f*100)}%</text>`;start+=f;return res}).join('')+`<text x="225" y="144" text-anchor="middle" style="font-size:22px;fill:#243145">${fmt(total)}</text><text x="225" y="166" text-anchor="middle">${t(agg)}</text>`;return}let body='';if(type==='scatter'){let lo=Math.min(...pairs.map(p=>p[0])),hi=Math.max(...pairs.map(p=>p[0]));body=pairs.map(p=>`<circle cx="${58+(p[0]-lo)/(hi-lo||1)*565}" cy="${yy(p[1])}" r="4" fill="#5369ed" opacity=".6"><title>${p[0]}, ${p[1]}</title></circle>`).join('')+`<text x="58" y="275">${fmt(lo)}</text><text x="620" y="275" text-anchor="end">${fmt(hi)}</text>`}else{let w=567/pairs.length,xx=i=>58+w*(i+.5);if(type==='line'){let coords=pairs.map((p,i)=>`${xx(i)},${yy(p[1])}`).join(' ');body=`<polygon points="${xx(0)},245 ${coords} ${xx(pairs.length-1)},245" fill="#eef0ff"/><polyline points="${coords}" fill="none" stroke="#5369ed" stroke-width="3"/>`+pairs.map((p,i)=>`<circle cx="${xx(i)}" cy="${yy(p[1])}" r="4" fill="#5369ed"><title>${esc(p[0])}: ${fmt(p[1])}</title></circle>`).join('')}else body=pairs.map((p,i)=>`<rect class="bar" data-cat="${esc(p[0])}" data-col="${esc(x)}" x="${58+i*w+w*.21}" y="${Math.min(yy(p[1]),yy(0))}" width="${w*.58}" height="${Math.max(1,Math.abs(yy(p[1])-yy(0)))}" rx="4" fill="${colors[i%colors.length]}"><title>${esc(p[0])}: ${fmt(p[1])}</title></rect>`).join('');body+=pairs.map((p,i)=>`<text x="${xx(i)}" y="272" text-anchor="middle" style="font-size:${pairs.length>12?8:11}px">${esc(String(p[0]).slice(0,12))}</text>`).join('')}svg.innerHTML=grid+body;svg.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{if(type==='hist')return;let a={op:'filter',c:b.dataset.col,method:'equals',v:b.dataset.cat};let out=applyRecipe(a);commit(out.r,t('filter')+': '+a.v,out.code,a)})}
function pipelineView(){return `<div class="panel"><section class="card"><h2>${t('steps')}</h2><div class="step"><span class="stepnum">00</span><span>${t('source')} · ${source.length} ${t('records')}</span></div>${history.map((s,i)=>`<div class="step"><span class="stepnum">${String(i+1).padStart(2,'0')}</span><span>${s.recipe?t(s.recipe.op):esc(s.label)}</span><span class="pill">${(i+1<history.length?history[i+1].before:rows).length}</span></div>`).join('')}<div class="tools"><button id="clear">${t('clear')}</button><button id="exportFlow">${t('exportFlow')}</button><button id="importFlow">${t('importFlow')}</button></div></section><section class="card"><div class="cardhead"><h2>${t('python')}</h2><button id="exportPy" class="small">↓ .py</button></div><pre class="mono">${esc(py())}</pre><div class="callout">${t('notall')}</div></section></div>`}
function helpView(){let steps=lang==='zh'?[['01 · 加载数据','导入 CSV、TSV、JSON，粘贴文本或加载允许 CORS 的 URL。内置 240 行零售数据，可把自己的数据设为默认。'],['02 · 发现问题','完整率、重复行、描述性统计和 IQR 异常值帮助你发现质量问题；数据表支持编辑和搜索。'],['03 · 可视化分析','柱状图点击筛选，折线图观察趋势，散点图发现关系，直方图查看分布，相关矩阵对比多个指标。'],['04 · 变换与复用','使用分组聚合、透视、连接和计算列构建分析流水线，撤销 / 重做，并导出 CSV、JSON、SVG 和 Python。']]:[['01 · Load data','Import CSV, TSV or JSON, paste text, or load a CORS-enabled URL. Start with 240 retail records and save your own default.'],['02 · Find issues','Completeness, duplicate counts, descriptive statistics and IQR outliers reveal quality issues. Edit and search in the table.'],['03 · Explore visually','Click bars to filter, follow trends with lines, discover relations with scatter plots, examine distributions with histograms and compare correlations.'],['04 · Transform & reuse','Build a pipeline using aggregation, pivots, joins and calculated columns. Undo / redo and export CSV, JSON, SVG and Python.']];return `<section class="card"><h2 style="font-size:22px">${t('guide')}</h2><div class="cards3" style="grid-template-columns:repeat(2,1fr);margin-top:24px">${steps.map(a=>`<div class="card"><h2>${a[0]}</h2><p style="margin-top:12px">${a[1]}</p></div>`).join('')}</div><div class="callout">${t('notall')}<br>${t('limit')}</div></section>`}
function modal(html,onload){$('dialog')?.remove();let d=document.createElement('dialog');d.innerHTML=html;document.body.append(d);d.showModal();d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());onload?.(d)}
function importModal(){modal(`<h2>${t('settitle')}</h2><div class="drop"><div style="font-size:30px;color:#8492ed;margin-bottom:12px">↥</div><button class="primary" id="choose">${t('choose')}</button><p style="margin-top:12px;font-size:12px">${t('filetip')}</p></div><div class="form">${field('format','format',['csv','tsv','json'],'csv')}<label>${t('paste')}<textarea id="paste" rows="5" placeholder="date,region,revenue&#10;2025-01-01,East,1200"></textarea></label><label>${t('url')}<input id="url" type="url" placeholder="https://example.com/data.csv"></label><p style="font-size:11px">${t('urltip')}</p></div><div class="modalfooter"><button data-close>${t('cancel')}</button><button class="primary" id="load">${t('load')}</button></div>`,d=>{$('#choose').onclick=()=>$('#file').click();$('#load').onclick=async()=>{try{let text=$('#paste').value,url=$('#url').value;if(url){let response=await fetch(url);if(!response.ok)throw Error('HTTP '+response.status);text=await response.text()}loadData(E.parse(text,$('#format').value),url?url.split('/').pop():'Imported data');d.close()}catch(e){toast(t('error')+e.message)}}})}
function loadData(data,filename){if(!data.length)throw Error(lang==='zh'?'数据为空':'Dataset is empty');if(data.length>50000)throw Error(lang==='zh'?'最多支持 50,000 行':'Maximum 50,000 rows');rows=data;source=structuredClone(data);history=[];redoStack=[];name=filename;page=0;search='';render();toast(t('success'))}
function exportModal(){modal(`<h2>${t('exporttitle')}</h2><div class="tools">${['exportCsv','exportJson','exportPy','exportFlow'].map(k=>`<button id="${k}">${t(k)}</button>`).join('')}</div><p>${rows.length} ${t('records')} · ${cols().length} ${t('cols')}</p><div class="modalfooter"><button data-close>${t('close')}</button></div>`,d=>{d.querySelector('#exportCsv').onclick=()=>download(E.csv(rows),'framelab-result.csv','text/csv');d.querySelector('#exportJson').onclick=()=>download(JSON.stringify(rows,null,2),'framelab-result.json','application/json');d.querySelector('#exportPy').onclick=()=>download(py(),'framelab-analysis.py');d.querySelector('#exportFlow').onclick=exportFlow})}
function exportFlow(){if(history.some(s=>!s.recipe)){toast(lang==='zh'?'单元格编辑不支持流程重放，请导出结果数据':'Cell edits cannot be replayed; export result data instead');return}download(JSON.stringify({version:1,steps:history.map(s=>s.recipe)},null,2),'framelab-workflow.json','application/json')}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;page=0;render()});$('#language').onclick=()=>{lang=lang==='zh'?'en':'zh';localStorage.setItem('fl-lang',lang);render()};$('#undo').onclick=()=>{if(history.length){let s=history.pop();redoStack.push({...s,after:structuredClone(rows)});rows=s.before;page=0;render()}};$('#redo').onclick=()=>{let s=redoStack.pop();if(s){history.push(s);rows=s.after;render()}};$('#import').onclick=importModal;$('#export').onclick=exportModal;document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{let a={op:'sort',c:b.dataset.sort,method:'asc'},out=applyRecipe(a);commit(out.r,t('sort'),out.code,a)});document.querySelectorAll('[data-cell]').forEach(td=>td.ondblclick=()=>{td.contentEditable='true';td.textContent=rows[Number(td.dataset.row)][td.dataset.cell]??'';td.focus();let old=td.textContent;td.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();td.blur()}if(e.key==='Escape'){td.textContent=old;td.blur()}};td.onblur=()=>{if(td.textContent!==old){let r=structuredClone(rows),v=td.textContent,c=td.dataset.cell,i=Number(td.dataset.row);r[i][c]=v===''?null:E.numeric(rows,c)&&E.num(v)?Number(v):v;commit(r,lang==='zh'?'编辑单元格':'Edit cell',`df.iloc[${i}, df.columns.get_loc(${JSON.stringify(c)})] = ${r[i][c]===null?'None':JSON.stringify(r[i][c])}`)}else render()}});
const on=(id,fn)=>{let el=$('#'+id);if(el)el.onclick=fn};on('prev',()=>{page--;render()});on('next',()=>{page++;render()});if($('#search'))$('#search').oninput=e=>{search=e.target.value;page=0;render();$('#search').focus();$('#search').setSelectionRange(search.length,search.length)};on('saveDefault',()=>{try{localStorage.setItem('fl-default',JSON.stringify(rows));toast(t('defaultsaved'))}catch{toast(t('error')+'Storage quota exceeded')}});on('clearDefault',()=>{localStorage.removeItem('fl-default');loadData(E.demo(),'Retail analytics.csv')});on('reset',()=>loadData(E.demo(),'Retail analytics.csv'));on('quickfilter',()=>{op='filter';view='transform';render()});if($('#op'))$('#op').onchange=e=>{op=e.target.value;render()};on('apply',()=>{try{let val=id=>$('#'+id)?.value||'',a={op,c:val('col'),method:val('method'),v:val('value'),second:val('second'),metric:val('metric'),agg:val('agg'),newname:val('newname')},out=applyRecipe(a);commit(out.r,t(op),out.code,a)}catch(e){toast(t('error')+e.message)}});['charttype','chartx','charty','chartagg'].forEach(id=>{if($('#'+id))$('#'+id).onchange=e=>{if(id==='charttype')chartType=e.target.value;if(id==='chartx')chartX=e.target.value;if(id==='charty')chartY=e.target.value;if(id==='chartagg')chartAgg=e.target.value;render()}});on('downloadChart',()=>download(new XMLSerializer().serializeToString($('#explorechart')),'framelab-chart.svg','image/svg+xml'));on('clear',()=>{rows=structuredClone(source);history=[];redoStack=[];render()});on('exportPy',()=>download(py(),'framelab-analysis.py'));on('exportFlow',exportFlow);on('importFlow',()=>{modal(`<h2>${t('importFlow')}</h2><textarea id="flow" rows="12"></textarea><div class="modalfooter"><button data-close>${t('cancel')}</button><button id="replay" class="primary">${t('apply')}</button></div>`,d=>{$('#replay').onclick=()=>{let saved={rows:structuredClone(rows),history:[...history],redoStack:[...redoStack]};try{let flow=JSON.parse($('#flow').value);if(flow.version!==1||!Array.isArray(flow.steps))throw Error('Unsupported workflow');for(let a of flow.steps){let out=applyRecipe(a);commit(out.r,t(a.op),out.code,a)}d.close()}catch(e){rows=saved.rows;history=saved.history;redoStack=saved.redoStack;render();toast(t('error')+e.message)}}})})}
$('#file').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{loadData(E.parse(await file.text(),file.name.split('.').pop().toLowerCase()),file.name);$('dialog')?.close()}catch(error){toast(t('error')+error.message)}e.target.value=''};
document.addEventListener('dragover',e=>e.preventDefault());document.addEventListener('drop',async e=>{e.preventDefault();let file=e.dataTransfer.files[0];if(file)try{loadData(E.parse(await file.text(),file.name.split('.').pop().toLowerCase()),file.name)}catch(error){toast(t('error')+error.message)}});render();
